import{_ as a,o as e,c as n,S as l}from"./chunks/framework.D1Ss-Xl7.js";const u=JSON.parse('{"title":"数据库查询的N+1问题","description":"","frontmatter":{"title":"数据库查询的N+1问题","date":"2021-02-20 13:44","comments":true,"archives":2021,"tags":["database"]},"headers":[],"relativePath":"posts/2021-02-20-sql-n-1/index.md","filePath":"posts/2021/2021-02-20-sql-N+1.md"}'),o={name:"posts/2021-02-20-sql-n-1/index.md"};function r(p,s,t,c,i,d){return e(),n("div",null,[...s[0]||(s[0]=[l('<p>在工作中有时也会涉及到后端开发，后端开发的性能优化多是查询优化。类似前端 DOM 操作很消耗性能，后端开发数据库查询次数也会相当消耗性能。我们在开发中应该尽量减少 SQL 查询次数，避免 N+1 问题来提升性能。接下来就来介绍数据库查询的 N+1 问题。</p><h2 id="sql-n-1" tabindex="-1">SQL N+1 <a class="header-anchor" href="#sql-n-1" aria-label="Permalink to &quot;SQL N+1&quot;">​</a></h2><p>举一个简单的例子，数据库中有一张 <code>cars</code> 表存储汽车的相关信息，还有一张 <code>wheels</code> 表存储汽车的轮胎信息。</p><p>查询汽车的语句是：</p><div class="language-sql line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">SELECT</span><span style="color:#D73A49;"> *</span><span style="color:#D73A49;"> FROM</span><span style="color:#24292E;"> cars;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>查询每个汽车的轮子的语句是：</p><div class="language-sql line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">SELECT</span><span style="color:#D73A49;"> *</span><span style="color:#D73A49;"> FROM</span><span style="color:#24292E;"> wheels </span><span style="color:#D73A49;">WHERE</span><span style="color:#24292E;"> car_id </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> ${car_id};</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>这里的 N 就是汽车的数量，如果需要知道每个汽车的轮胎信息那就正好需要查询 <code>N+1</code> 次。</p><h2 id="解决-n-1" tabindex="-1">解决 N+1 <a class="header-anchor" href="#解决-n-1" aria-label="Permalink to &quot;解决 N+1&quot;">​</a></h2><p>如果汽车和轮胎是一对一的关系可以通过使用 <code>join</code> 语句来减少数据库查询次数。把查询降为 1 次。修正之后的查询语句是：</p><div class="language-sql line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">SELECT</span><span style="color:#24292E;"> cars.</span><span style="color:#D73A49;">*</span><span style="color:#24292E;">, wheels.</span><span style="color:#D73A49;">*</span><span style="color:#D73A49;"> FROM</span><span style="color:#24292E;"> cars </span><span style="color:#D73A49;">INNER JOIN</span><span style="color:#24292E;"> wheels </span><span style="color:#D73A49;">ON</span><span style="color:#005CC5;"> wheels</span><span style="color:#24292E;">.</span><span style="color:#005CC5;">car_id</span><span style="color:#D73A49;"> =</span><span style="color:#005CC5;"> cars</span><span style="color:#24292E;">.</span><span style="color:#005CC5;">id</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>如果汽车和轮胎是一对多的关系可以通过使用：</p><div class="language-sql line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">SELECT</span><span style="color:#D73A49;"> *</span><span style="color:#D73A49;"> FROM</span><span style="color:#24292E;"> cars;</span></span>\n<span class="line"><span style="color:#D73A49;">SELECT</span><span style="color:#D73A49;"> *</span><span style="color:#D73A49;"> FROM</span><span style="color:#24292E;"> wheels </span><span style="color:#D73A49;">WHERE</span><span style="color:#005CC5;"> wheels</span><span style="color:#24292E;">.</span><span style="color:#005CC5;">car_id</span><span style="color:#D73A49;"> IN</span><span style="color:#24292E;"> (</span><span style="color:#005CC5;">1</span><span style="color:#24292E;">,</span><span style="color:#005CC5;">2</span><span style="color:#24292E;">,</span><span style="color:#005CC5;">3</span><span style="color:#24292E;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>一次性查询所有需要的轮胎把查询降为两次。</p><h2 id="现有框架解决方案" tabindex="-1">现有框架解决方案 <a class="header-anchor" href="#现有框架解决方案" aria-label="Permalink to &quot;现有框架解决方案&quot;">​</a></h2><h3 id="django" tabindex="-1">Django <a class="header-anchor" href="#django" aria-label="Permalink to &quot;Django&quot;">​</a></h3><p>Django 可以使用<a href="https://docs.djangoproject.com/en/3.1/ref/models/querysets/#select-related" target="_blank" rel="noreferrer">select-related</a> 和 <a href="https://docs.djangoproject.com/en/3.1/ref/models/querysets/#prefetch-related" target="_blank" rel="noreferrer">prefetch-related</a>来解决这个问题。</p><p><code>select-related</code> 主要用于一对一的关系，而 <code>prefetch-related</code> 主要用于多对多或者多对一的关系。</p><h3 id="ruby-on-rails" tabindex="-1">Ruby on Rails <a class="header-anchor" href="#ruby-on-rails" aria-label="Permalink to &quot;Ruby on Rails&quot;">​</a></h3><p>使用 <a href="https://api.rubyonrails.org/v6.1.3/classes/ActiveRecord/QueryMethods.html#method-i-includes" target="_blank" rel="noreferrer">includes</a> 来解决 N+1 问题。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>后端开发需要时刻注意 N+1 问题， 在开发模式下，日志会输出 SQL 查询语句，需要多加注意。也可以使用一些工具来检测这个问题。</p><h2 id="参考" tabindex="-1">参考 <a class="header-anchor" href="#参考" aria-label="Permalink to &quot;参考&quot;">​</a></h2><p><a href="https://stackoverflow.com/questions/97197/what-is-the-n1-selects-problem-in-orm-object-relational-mapping" target="_blank" rel="noreferrer">What is the “N+1 selects problem” in ORM</a></p><p><a href="https://guides.rubyonrails.org/active_record_querying.html" target="_blank" rel="noreferrer">Active Record Query Interface</a></p>',25)])])}const y=a(o,[["render",r]]);export{u as __pageData,y as default};
